package main

// Configuration generation for setup. The generated bytes are built in memory,
// the state path is baked absolute under the target directory, and the real
// loader validates the exact bytes before anything is published. A seed's
// relative legacy root is resolved against the seed file's own directory; the
// loader's existing relative-state_path semantics are not changed.
//
// The timezone is an explicit --tz or the host's IANA zone. "Local", the empty
// name and time.LoadLocation's own ""→UTC fallback are rejected so a generated
// configuration always names a real zone that resolves the same way in every
// process.

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/huyle-gradion/pilot-timesheet/internal/timesheet"
)

// setupStateName is the state file a generated configuration points at.
const setupStateName = "state.json"

// setupConfigBytes builds and validates the configuration. The state path is
// absolute under the target directory so later commands do not depend on cwd.
func setupConfigBytes(opts setupOptions, seed *timesheet.Config, dir string) (data []byte, timezone, source string, err error) {
	timezone, source, err = setupTimezone(opts.timezone)
	if err != nil {
		return nil, "", "", err
	}
	var cfg timesheet.Config
	if seed != nil {
		cfg = *seed
		if cfg.Migration != nil && strings.TrimSpace(cfg.Migration.LegacyRoot) != "" && !filepath.IsAbs(cfg.Migration.LegacyRoot) {
			cfg.Migration.LegacyRoot = filepath.Join(filepath.Dir(opts.seedConfigPath), cfg.Migration.LegacyRoot)
		}
	} else {
		cfg.Projects = make([]timesheet.Project, 0, len(opts.projects))
		for _, seed := range opts.projects {
			cfg.Projects = append(cfg.Projects, timesheet.Project{
				ID:                    seed.id,
				Name:                  seed.name,
				DefaultClassification: seed.classification,
			})
		}
		cfg.RequiredEnv = append([]string(nil), defaultSetupEnvNames()...)
	}
	cfg.Timezone = timezone
	cfg.StatePath = filepath.Join(dir, setupStateName)
	data, err = json.MarshalIndent(cfg, "", "  ")
	if err != nil {
		return nil, "", "", fmt.Errorf("setup: cannot render the configuration: %v", err)
	}
	data = append(data, '\n')
	if err := validateSetupConfig(data); err != nil {
		return nil, "", "", err
	}
	return data, timezone, source, nil
}

// validateSetupConfig runs the real loader over the exact bytes that would be
// published. The probe lives outside the target directory, so a field-named
// failure creates nothing under $HOME/.timesheet.
func validateSetupConfig(data []byte) error {
	probeDir, err := os.MkdirTemp("", "timesheet-setup-validate-")
	if err != nil {
		return fmt.Errorf("setup: cannot validate the generated configuration: %v", err)
	}
	defer func() { _ = os.RemoveAll(probeDir) }()
	probe := filepath.Join(probeDir, defaultConfigName)
	if err := os.WriteFile(probe, data, 0o600); err != nil {
		return fmt.Errorf("setup: cannot validate the generated configuration: %v", err)
	}
	if _, err := timesheet.LoadConfig(probe); err != nil {
		return fmt.Errorf("setup: generated configuration does not load: %v", err)
	}
	return nil
}

// defaultSetupEnvNames are the credential names a config generated without a
// seed declares. Only names are ever emitted; values never are.
func defaultSetupEnvNames() []string {
	return []string{"GITHUB_TOKEN", "GCAL_ICS_URL"}
}

// setupEnvTemplate is the commented credential-name template. It contains no
// values and no assignments, so it can never leak or imply a credential.
func setupEnvTemplate(names []string) []byte {
	var b strings.Builder
	b.WriteString("# timesheet credentials\n#\n")
	b.WriteString("# Values are yours to add: setup never reads, writes or prints them.\n")
	b.WriteString("# Add one line per name below: the name, an equals sign, then the value.\n")
	b.WriteString("# Only the compiled binary reads this file (via --env-file).\n")
	for _, name := range names {
		b.WriteString("#\n# ")
		b.WriteString(name)
		b.WriteString("\n")
	}
	return []byte(b.String())
}

func describeSetupProjects(seed *timesheet.Config, projects []projectSeed) string {
	var parts []string
	if seed != nil {
		for _, p := range seed.Projects {
			parts = append(parts, fmt.Sprintf("%s=%q", p.ID, p.Name))
		}
	} else {
		for _, p := range projects {
			parts = append(parts, fmt.Sprintf("%s=%q", p.id, p.name))
		}
	}
	if len(parts) == 0 {
		return "no projects"
	}
	return "projects " + strings.Join(parts, ", ")
}

// setupTimezone returns the configured IANA zone: the explicit --tz when given,
// otherwise the host's own zone. It never guesses Local or UTC.
func setupTimezone(explicit string) (string, string, error) {
	if explicit != "" {
		if !validIANAZone(explicit) {
			return "", "", setupUsagef("setup: --tz %q is not a recognised IANA timezone", explicit)
		}
		return explicit, "--tz", nil
	}
	zone, err := hostTimezone()
	if err != nil {
		return "", "", setupUsagef("setup: cannot determine the host IANA timezone; pass --tz <IANA zone>: %v", err)
	}
	return zone, "the host zone", nil
}

func hostTimezone() (string, error) {
	return hostTimezoneFrom(os.Getenv("TZ"), "/etc/timezone", "/etc/localtime")
}

// validIANAZone rejects the empty name, time.LoadLocation's ""→UTC fallback and
// the machine-dependent pseudo-zone "Local".
func validIANAZone(name string) bool {
	if strings.TrimSpace(name) == "" || name == "Local" {
		return false
	}
	_, err := time.LoadLocation(name)
	return err == nil
}

// hostTimezoneFrom resolves the host zone from a TZ value, the
// Debian/Omarchy-style /etc/timezone file, then the /etc/localtime symlink. The
// paths are parameters so the resolution order is testable without touching
// the machine's zone files.
func hostTimezoneFrom(tzEnv, etcTimezone, etcLocaltime string) (string, error) {
	if tz := strings.TrimSpace(tzEnv); tz != "" {
		tz = strings.TrimPrefix(tz, ":")
		if validIANAZone(tz) {
			return tz, nil
		}
	}
	if data, err := os.ReadFile(etcTimezone); err == nil {
		tz := strings.TrimSpace(string(data))
		if validIANAZone(tz) {
			return tz, nil
		}
	}
	resolved, err := filepath.EvalSymlinks(etcLocaltime)
	if err != nil {
		return "", fmt.Errorf("no valid TZ value or /etc/timezone, and /etc/localtime cannot be resolved")
	}
	if idx := strings.Index(resolved, "zoneinfo/"); idx >= 0 {
		tz := strings.TrimPrefix(resolved[idx+len("zoneinfo/"):], "/")
		if validIANAZone(tz) {
			return tz, nil
		}
	}
	return "", fmt.Errorf("/etc/localtime does not name an IANA zone")
}
